-- [questID] = { title, text, level, group, frequency, xp, money, objectives, starts / ends = { npc = {ids}, object = {ids}, item = {ids} }, races, classes, factions, accepted = spots, objectiveSpots = { [index] = spots } }
local _, ns = ...
ns.data.quests = {
  [488]={accepted={[1438]={60.4,56.2,1}},classes={"ROGUE"},description="Eager for work, I see.  Lucky for you a day never goes by that I don't wish I had a fledgling rogue to perform my bidding.\n\nYou see, Sica, I can make you very happy and provide you with things you never dreamed of having.  But in order for that to happen you must bring me certain items.\n\nMy business in the forest often requires certain. . .reagents.  Fetch for me 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.\n\nLet's keep this our little secret, night elf.",done=0,ends={npc={2150}},factions={"Alliance"},frequency=0,group=0,level=5,objectives={{need=3,text="0/3  ",type="item"},{need=3,text="0/3  ",type="item"},{need=3,text="0/3  ",type="item"}},progressText="Have you been a busy little bee, Sica?  I've been waiting for you to bring me what I need.",races={"NightElf"},required={{count=3,item=3409},{count=3,item=3411},{count=3,item=3412}},seenBy=1,text="Bring Zenn Foulhoof outside of Dolanaar 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.",title="Zenn's Bidding",zone="Teldrassil"},
  [928]={description="While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.\n\nSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.\n\nMind you stay on the road though, Sica. There are dangerous beasts in the forests of late.",done=0,level=5,objectives={{need=1,text="Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.",type="log"}},seenBy=1,text="Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.",title="Crown of the Earth",zone="Shadowglen"},
  [969]={description="Ah, I can tell just by lookin' at ya -- you be wantin' to make a lucky charm. Mau'ari always knows!\n\nTo da south. you'll find a canyon, an' giants made a' solid ice. The giants sometimes be carryin' dem, but ya can always gather da shards yerself from da canyon. These shards have a powerful reflective quality.\n\nBring back 10 frostmaul shards, and my lucky charm will be yours.",done=0,level=60,objectives={{need=10,text="0/10 Frostmaul Shards",type="item"}},seenBy=1,text="Collect 10 Frostmaul Shards for Witch Doctor Mau'ari in Everlook.",title="Luck Be With You",zone="Winterspring"},
  [2159]={choices={{count=5,item=2070},{count=5,item=159}},completionText="Ah yes, the delivery of herbs from Shadowglen.  It is a shame Porthannius could not bring it himself, for we have much to discuss, he and I.  But I am glad to get the herbs nonetheless, and I am glad you came.\n\nWhile you are here, please, rest yourself.  Heroes must keep their strength and spirits high, and must find rest and solace whenever they may.  For to neglect one's peace of body and mind is a sure path to failure.\n\nSo... rest.",description="Greetings, young rogue.  Can you offer me aid?  I have a package of herbs that I must deliver to the town of Dolanaar.  But I still have business with the druids of Shadowglen and cannot yet leave.\n\nCan you deliver this package for me?  It must be sent to Innkeeper Keldamyr, at the Dolanaar inn.  It lies along the road, to the south.",done=1,ends={npc={6736}},level=5,money=0,objectives={{need=1,text="Bring the Dolanaar Delivery to Innkeeper Keldamyr.",type="log"}},progressText="How might I be of service to you, young one?  Are you here to rest in the inn?  Do you require a hearthstone?",rep={Darnassus=25},required={{count=1,item=7627}},rewardXP=110,seenBy=1,text="Bring the Dolanaar Delivery to Innkeeper Keldamyr.",title="Dolanaar Delivery",xp=110,xpByLevel={[6]=110},zone="Teldrassil"},
  [2882]={description="This map shows a stretch of beach with a southern face.  Below the map are words, elegantly written...\n\n\nSouth of Wheedle\nSouth of home\nFind a mast and flag and bones\nDig you there, if you be bold\nDig and claim Cuergo's gold!\nA key you'll need and a key you'll see\nThe men you face take blood as fee.",done=0,level=45,objectives={{need=1,text="0/1 Cuergo's Key",type="item"}},seenBy=1,text="Find Cuergo's gold!",title="Cuergo's Gold",zone="Treasure Map"},
  [3449]={description="Magic was once as revered as Elune herself to some elves. Some of their most powerful mages created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places.\n\nI would very much like rubbings of these runes from the Ruins of Eldarath. I have a kit for you to make the rubbings with, but it will be up to you to find them. Be careful though, the Explorer's League isn't the only one interested in Eldarath.",done=0,level=52,objectives={{need=1,text="1/1 Rubbing: Rune of Beth'Amara",type="item"},{need=1,text="1/1 Rubbing: Rune of Jin'yael",type="item"},{need=1,text="1/1 Rubbing: Rune of Markri",type="item"},{need=1,text="1/1 Rubbing: Rune of Sael'hai",type="item"}},seenBy=1,text="Using the Drawing Kit, make rubbings of the Rune of Beth'Amara, the Rune of Jin'yael, the Rune of Markri, and the Rune of Sael'hai before heading to the small island off of the southern peninsula of Azshara and signaling Pilot Xiggs Fuselighter to pick them up.",title="Arcane Runes",zone="Ironforge"},
  [3512]={description="Tylesser, our first step will be to devise a method to speak with Eranikus through the gem.  He lies in a precarious state between sleep and death now, twisted within a weave of nightmares.  Though the essence you have given me is badly tainted, there is a chance we can reach him.\n\nTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker.  He is a human medium who speaks for the dead.  Though Eranikus is not truly dead, he may be of aid to us still.",done=0,level=55,seenBy=1,text="Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.",title="In Eranikus' Own Words",zone="Swamp of Sorrows"},
  [3701]={description="Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.\n\nIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, Tylesser. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.",done=0,level=54,objectives={{need=12,text="0/12 Information Recovered",type="object"}},seenBy=1,text="Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.",title="The Smoldering Ruins of Thaurissan",zone="Ironforge"},
  [4005]={description="Take this bag of supplies with you to Tanaris. Travel to Lost Rigger Cove, and look for a circle of stones.\n\nThe eastmost peninsula is the secret...\n\nFrom this circle only, read from the book of Aquor; summon the only creature that can transform the items you collected into a totem to fight Blazerunner.\n\nAquementas will not be pleased to be awakened, but remember, you must remain in the circle for him to transform the items.",done=0,level=54,objectives={{need=1,text="0/1 Silver Totem of Aquementas",type="item"}},seenBy=1,text="Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.\n\nUse the Book of Aquor to summon Aquementas.\n\nAfter you have the completed totem, take it to J.D. Collie in Marshal's Refuge.",title="Aquementas",zone="Un'Goro Crater"},
  [5065]={description="The troll with whom you spoke did not tell the truth.  The two tablets you gained for him spoke of containing the essence of Hakkar, but there is more to that legend.  I have studied long, and found that there are six Tablets of Mosh'aru, not two!  Six!\n\nAnd I fear that we will not like what secrets the others hold..\n\nFind the third and fourth tablets of Mosh'aru.  They're in the Eastern Plaguelands, held by the mossflayer trolls. Find them, and bring them to me.",done=0,level=58,objectives={{need=1,text="0/1 Third Mosh'aru Tablet",type="item"},{need=1,text="0/1 Fourth Mosh'aru Tablet",type="item"}},seenBy=1,text="Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris.",title="The Lost Tablets of Mosh'aru",zone="Eastern Plaguelands"},
  [5121]={description="While we still know very little about why the furbolg have been ingesting this strange substance, I do think it's best that we put a stop to it before it gets out of hand.\n\nThe Winterfall furbolg are not a normally aggressive tribe, and this change in their behavior leads me to think that they must be under orders from their chief. We most likely can't undo the damage that has already been done, but I think that if their leader is slain, they will not get any worse.\n\nHead east to Winterfall Village.",done=0,level=59,objectives={{need=1,text="0/1 High Chief Winterfall slain",type="monster"}},seenBy=1,text="Donova Snowden in Winterspring wants you to defeat High Chief Winterfall.",title="High Chief Winterfall",zone="Winterspring"},
  [5159]={description="Thank the spirits, Tylesser. They are the ones that have come to your aid, not me.\n\nI give this purified water to you now. Please give my regards to Greta and my best wishes. She is tackling something greater than many of us... as I'm sure she will soon find out.\n\nThe Shadow Council is not a force to be trifled with, Tylesser. Remember that.\n\nGo now. Take the water and return to Greta.",done=0,level=54,objectives={{need=1,text="Take the Purified Moon Well Water to Greta Mosshoof in Felwood.",type="log"}},seenBy=1,text="Take the Purified Moon Well Water to Greta Mosshoof in Felwood.",title="Cleansed Water Returns to Felwood",zone="Felwood"},
  [5163]={description="It's all ready, Tylesser!\n\nNow, I sent some mail to my friends already, telling them that I have a surprise for them. This is where you come in!\n\nI'm going to give you my mechanical yeti, and you need to surprise them by paying each of my friends a visit, turning the yeti on and sending it towards them.\n\n Once you have shown Legacki in Everlook, Sprinkle in Gadgetzan, and Quixxil in Marshal's Refuge, come back and tell me what happened!\n\nPlease bring my yeti back to me then, too.",done=0,level=58,objectives={{need=1,text="1/1 Scare Legacki",type="monster"},{need=1,text="0/1 Scare Sprinkle",type="monster"},{need=1,text="0/1 Scare Quixxil",type="monster"}},seenBy=1,text="Take Umi's Mechanical Yeti and scare her friends with it:\n\nLegacki in Everlook (Winterspring)\nSprinkle in Gadgetzan (Tanaris)\nQuixxil in Marshal's Refuge (Un'Goro Crater)\n\nWhen you are done, bring the Mechanical Yeti back to Umi.",title="Are We There, Yeti?",zone="Winterspring"},
  [5245]={description="The highborne spirits are miserable creatures, that's for sure. They are still searching for pieces of the very thing that has cursed them to Kel'Theril forever -- the stolen relic.\n\nIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.\n\nNow, I can't tell you a thing about what you find, but I do know of someone who might... Aurora Skycaller; she dwells near the Northpass Tower in the northern part of Eastern Plaguelands.",done=0,level=56,objectives={{need=1,text="1/1 First Relic Fragment",type="item"},{need=1,text="1/1 Second Relic Fragment",type="item"},{need=1,text="1/1 Third Relic Fragment",type="item"},{need=1,text="1/1 Fourth Relic Fragment",type="item"}},seenBy=1,text="Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands.",title="Troubled Spirits of Kel'Theril",zone="Winterspring"},
  [6030]={description="A recluse medium found in these parts by the name of Umbranse has provided the Argent Dawn with quite a literary masterpiece... one that amounts to quite possibly the largest collection of jibber-jabber I've ever seen written.\n\nOne of the Dawn's most respected leaders, Duke Nicholas Zverenhoff, is a brilliant linguist.  Could you take this to him for me - for a reward, of course?  Light's Hope Chapel - that's where he's currently at, far in the eastern part of the Eastern Plaguelands.",done=0,level=52,objectives={{need=1,text="Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands.",type="log"}},seenBy=1,text="Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands.",title="Duke Nicholas Zverenhoff",zone="Winterspring"},
  [8470]={description="You have found one of the Deadwood furbolg's ritual totems.  The totem itself is of non-descript construction, but a palpable sense of despair emanates from it.  If there were any object that might best exemplify the corruption that the Deadwood furbolg suffer under, this item would clearly be it.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.\n",done=0,level=55,objectives={{need=1,text="Unfriendly / Neutral Timbermaw Hold",type="reputation"}},seenBy=1,text="Take the Deadwood Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item.  The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them.",title="Deadwood Ritual Totem",zone="Felwood"},
  [79946]={description="Due to the... unfortunate nature of why he left the order, it would be bad comedy for Aeonas to die at the hands of the Scarlet Crusade now. The Crusade is an organization of zealots and lunatics and they've been growing increasingly brazen in their willingness to commit violence against anyone who they imagine to be enemies of the light. Go to the Scarlet Monastery in Tirisfal Glades and find out if Aeonas still lives.",done=0,level=40,objectives={{need=1,text="1/1 Learn more about Aeonas from Katherine (Optional)",type="monster"},{need=1,text="0/1 Find Aeonas in the Scarlet Monastery",type="monster"}},seenBy=1,text="Speak with Katherine to learn more about Aeonas, and then find him in the Scarlet Monastery.",title="A Brother In Need",zone="Paladin"},
  [83934]={description="Heya! You look like the \"resourceful adventurer\" type so maybe you can help me out. See, my brothers and I came from Kezan looking to start up a new business venture but we ran afoul of some pirates who stole our startup money. The people who are funding our operation back home aren't exactly what I'd call understanding, so we'd make it worth your while if are able to find any of the coin and return it. It's no ordinary gold but you should know it when you see it.",done=0,level=60,objectives={{need=1,text="0/1 Tarnished Undermine Real",type="object"}},seenBy=1,text="Bring a Tarnished Undermine Real to Pix Xizzix in Booty Bay.",title="Show Me the Money!",zone="Booty Bay"},
  [84150]={description="Well met, paladin.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.",done=0,level=60,objectives={{need=15,text="0/15 Winterspring Blood Sample",type="item"},{need=1,text="0/1 Lightforge Bracers",type="item"}},seenBy=1,text="Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Lightforge Bracers to Deliana in Ironforge.",title="An Earnest Proposition",zone="Ironforge"},
  [91688]={description="You've managed to cut a swath through the undead that have kept us trapped here for so many years, and for that we can never repay you.\n\nI have one more favor to ask, on behalf of us all. We know that there are druids at the summit. They protect Nordrassil and the Well of Eternity.\n\nWhy did they never come help us to escape?\n\nFor five years we have been trapped here. At last we have a glimmer of hope... but why didn't the druids come for us?\n\nLet someone know that we're still alive!",done=0,level=59,seenBy=1,text="Travel to the Summit of Eternity and speak with the druids about the survivor village.",title="To the Summit of Eternity",zone="Mount Hyjal"},
  [91883]={done=1,ends={npc={254131}},money=13800,seenBy=1,title="Spear of the Skylord",xp=4800},
  [92011]={description="I'm going to need some time to sort out which plans to build first. Something I've been meaning to do is hike up to the old Horde base and see what kind of treasure can be made out of whatever trash is laying around there.\n\nIf you are heading up there, and have the space to carry it, keep your eyes peeled for scrap metal, wire, or chunks of bat... droppings! Look, it has its uses okay!\n\nYou can find the remains of the horde encampment far up the mountain, even beyond the Elderwild settlement.",done=0,level=58,objectiveSources={[1]={["object:571603"]=1}},objectiveSpots={[1]={[2482]={49.4,32.4,1}}},objectives={{need=5,text="3/5 Frayed Wire",type="item"},{need=5,text="5/5 Calcified Excrement",type="item"},{need=5,text="5/5 Warped Metal Scrap",type="item"}},seenBy=1,text="Scavenge the remains of the Horde base and return 5 Frayed Wire, 5 Scrap Metal, and 5 Calcified Excrement to Kaylaena.",title="Rubble Rummage",zone="Mount Hyjal"},
  [92014]={accepted={[2482]={43.9,37.8,1}},after={[92015]=1},classes={"PALADIN"},description="Every time I take my attention off the supplies I've lugged up here for more than a few minutes, one of nature's finest thieves is pilfering and rummaging through it.\n\nThe damned foxes seem to have made a burrow beneath the boulders nearby. Apparently, me digging out this hole gave them an idea of their own.\n\nI'm working on a solution. Tell you what, bring back some of their fox tails. That'll teach them a lesson, and I'll hang the tails around the perimeter to scare the others off!",done=0,factions={"Alliance"},frequency=0,group=0,level=57,objectiveSources={[1]={["npc:249474"]=1}},objectiveSpots={[1]={[2482]={45.6,30.3,1}}},objectives={{need=9,text="0/9  ",type="item"}},offeredAt=59,races={"Human"},rewardXP=6000,rewards={{count=1,item=275633}},seenBy=1,starts={npc={249234}},text="Return 9 Rustleaf Fox Tails to Johun \"Punchy\" Dillas in Hyjal.",title="Fox Hole",zone="Mount Hyjal"},
  [92015]={accepted={[2482]={43.9,37.7,1}},classes={"PALADIN"},completionText="Not the kind of skunk-works you were expecting, is it? The right person comes along for every job, even the ones that stink.\n\nNow that I can get to more of these tools, I'll put together a thing or two here that might help us both out.",description="You say you want to help? Alright, I've got a task for ya.\n\nEver been skunked on a hot day? Nothing worse, I tell you. Bloody things cover everything within spittin' distance in the most vile lingering stench!\n\nA family of skunks have started making their home behind my equipment crates. Help me gently expel them from our perimeter and I'll think about sharing some of this gear, once we can get to it...\n\nI can't stress this enough: don't attack them - they WILL spray you!",done=1,ends={npc={249234}},factions={"Alliance"},frequency=0,group=0,level=56,money=0,objectiveSources={[1]={["object:653443"]=1}},objectiveSpots={[1]={[2482]={43.6,36.6,5}}},objectives={{need=6,text="0/6 Skunks repelled",type="monster"}},offeredAt=59,races={"Human"},rewardXP=1450,seenBy=1,starts={npc={249234}},text="Make skunks leave the area around Johun's equipment without killing them.",title="Area Denial Skunks",xp=1450,xpByLevel={[59]=1450},zone="Mount Hyjal"},
  [92020]={description="I've been taking notes and making drawings in my sketchbooks of all of the creatures living in Un'Goro Crater, and I made a few copies so that I can send them to people who might be interested!\n\nI have a sketchbook copy here that I've been meaning to get into the hands of the druids on Mount Hyjal, since I know that they love to study the natural world.\n\nHyjal's a bit of a trip, though. Do you think you could take it along in case you go there?",done=0,level=55,objectives={{need=1,text="Take Hol'anyee's Big Book of Big Lizards to a druid at the summit of Mount Hyjal.",type="log"}},seenBy=1,text="Take Hol'anyee's Big Book of Big Lizards to a druid at the summit of Mount Hyjal.",title="Hol'anyee's Big Book of Big Lizards",zone="Un'Goro Crater"},
  [92147]={done=1,ends={npc={260825}},money=20029,seenBy=1,title="Highfeather Helper",xp=6200},
  [92317]={done=1,ends={npc={256222}},money=12788,seenBy=1,title="Stolen Life",xp=4650},
  [92433]={description="Hey! I'm pretty busy trying to turn these scraps into something edible. You wanna help out? I could really use some more variety for this meal! It sure would be nice to have something different on the menu.\n\nThere's a goblin in Everlook who has this recipe for Savory Stag Sliders... perfect for tiny hands like mine. If you could cook up some of those, that would be great! You can get stag meat from the stags here on the mountain.",done=0,level=57,objectives={{need=6,text="0/6 Savory Stag Sliders",type="item"}},seenBy=1,text="Bring 6 Savory Stag Sliders to Hnaz Blunderflame in Elderwild.",title="Now We're Cooking",zone="Mount Hyjal"},
  [92500]={done=1,ends={npc={256222}},money=0,seenBy=1,title="A Bit of the Sky",xp=625},
  [92960]={accepted={[2482]={43.7,32.3,1}},after={[92015]=1},classes={"PALADIN"},description="A lingering demon presence remains to the east. Among them are the hellish beasts responsible for ravaging our kin, siphoning their power to use it against our allies.\n\nPenetrate their camp, locate these beasts and slay them. Retrieve any samples that remain.\n\nPerhaps there is something we can learn from these efforts.",done=0,factions={"Alliance"},frequency=0,group=0,level=59,objectiveSources={[1]={["npc:249230"]=1}},objectiveSpots={[1]={[2482]={52.6,34.9,1}}},objectives={{need=6,text="0/6  ",type="item"}},offeredAt=59,races={"Human"},rewardMoney=22713,rewardXP=6400,seenBy=1,starts={npc={263406}},text="Retrieve 6 Ephemeral Essences for Elaena Moonwhisper.",title="Siphoned Ephemeral Essence",zone="Mount Hyjal"},
  [93510]={completionText="On the shore of the lake you find a muddy anchor slowly being reclaimed by rust.",done=1,ends={object={654126}},money=17050,objectiveSpots={[1]={[1433]={30.5,57.1,1}}},progressText="Rust is taking over the anchor, but it's still intact and firmly stuck in the mud.",required={{count=1,item=274795}},rewardMoney=17050,rewardXP=6200,seenBy=1,title="Wake Memories",xp=6200},
  [93551]={accepted={[1433]={30.4,56.9,1}},after={[93510]=1},classes={"PALADIN"},completionText="This is where the world, as we knew it, ended. I'm here to tell you how it happened.",description="You went out of your way for the fading wishes of a lost soul--thank you, Tylesser. The sight of another spirit at the lake, thinking of two friends competing to see who can throw further--it's enough to draw me to this moment. Presence clings to the strongest bond with the living.\n\nWe never did skip a rock from one side to the other... \n\n<The ghost gazes across the lake.>\n\nI recall. Meet me in Mourning's Rest--the site of our last battle--next to the broken cannon near the destroyed tower on the cliff.",done=1,ends={npc={265375}},factions={"Alliance"},frequency=0,group=0,level=58,money=17050,objectiveSpots={[1]={[2482]={27.5,51,1}}},objectives={{need=1,text="0/1 Veteran of the Third War met in Mount Hyjal",type="monster"}},races={"Human"},rewardMoney=17050,rewardXP=6200,seenBy=1,starts={npc={255305}},text="Use the Embroidered Scabbard to meet the Veteran of the Third War in Mount Hyjal near the broken cannon in Mourning's Rest.",title="Praise",xp=6200},
  [93567]={accepted={[2482]={27.5,51,1}},after={[93551]=1},classes={"PALADIN"},completionText="You have a patient heart, Tylesser. Hearing the anguish and turmoil wracking my spirit has already begun to lift this weight from my soul.\n\nThank you for walking this far. I feel my presence here beginning to drift away.",description="This mountain cliff to the southeast... the remains of the tower. Seared into my mind, their harrowing screams still echo forever in memories.\n\nAllow me to unburden myself and tell you of my defeat.",done=1,ends={npc={265375}},factions={"Alliance"},frequency=0,group=0,level=58,money=4500,objectiveSpots={[1]={[2482]={27.5,51,1}}},objectives={{need=1,text="0/1 Veteran's story told",type="monster"}},progressText="There is more to put to rest. Conversations to have. Swords to lay down.",races={"Human"},required={{count=1,item=274795}},rewardMoney=4500,rewardXP=3100,seenBy=1,starts={npc={265375}},text="Allow the Veteran of the Third War to tell his story at the broken cannon in Mourning's Rest.",title="Ends Meet",xp=3100},
  [93827]={done=1,ends={npc={256660}},money=21175,seenBy=1,title="Windswept Wards",xp=6200},
  [93828]={accepted={[2482]={20.2,78.2,1}},after={[94504]=1},classes={"PALADIN"},completionText="These herbs are prime, dry--time to grind to dust.",description="The mountain's breath is damp here by the spring, and my herbs will not dry in this thick air. When our kin return from the wild, they hang their packs wherever the roots allow good air, spread through the den.\n\nGo now. Find the strands of dried herbs hung round our home and bring them to me. With them, I will weave wraps and wards to keep our spirits strong.",done=1,ends={npc={256626}},factions={"Alliance"},frequency=0,group=0,level=57,money=0,objectiveSpots={[1]={[2482]={21.4,77.8,10}}},objectives={{need=10,text="0/10 Dried Hanging Herbs",type="object"}},races={"Human"},rep={["Barkskin Burrow"]=325},rewardXP=3000,seenBy=1,starts={npc={256626}},text="Collect 10 Dried Hanging Herbs from around Barkskin Burrow and return them to Fennar Mossmane.",title="Herbs of the Hollow",xp=3000},
  [93830]={accepted={[2482]={20.2,78.2,1}},after={[94504]=1},classes={"PALADIN"},completionText="<Fennar strongly sniffs the waterskin.> Ahh, thank you kind one. As you can see, even one pouch's worth is a lot to share with our small spring.",description="The Deadwood dwell by a pond born of Mount Hyjal's snow melt. That water is pure, strong with the mountain's breath. We use it for our draughts and to save roots from death.\n\nHere, the springs run slow. Our source must be saved, and used with care. But their pond flows with life, it could fill our den twice over. Bring me a skin filled with that water, friend. Spirits will bless your steps, and our den will drink deep of the mountain's gift.",done=1,ends={npc={256626}},factions={"Alliance"},frequency=0,group=0,level=57,money=0,objectiveSpots={[1]={[2482]={22.8,66.3,1}}},objectives={{need=1,text="0/1 Waterskin filled",type="item"}},progressText="Drink if you must while you're at the pond, as long as you fill the waterskin back up ere you bring it back.",races={"Human"},rep={["Barkskin Burrow"]=325},required={{count=1,item=263030}},rewardXP=3000,seenBy=1,starts={npc={256626}},text="Fill a waterskin provided by Fennar Mossmane at the pond outside of the Deadwood Furbolg den.",title="Water of Hyjal",xp=3000},
  [93833]={accepted={[2482]={21.7,79.2,1}},after={[94504]=1},classes={"PALADIN"},description="The owls of Hyjal are more than feathers and flight. Their talons, their plumes, even the bones whisper of the wild. We use these gifts to craft talismans, charms that bind the spirits and shield our kin.\n\nBut the owls do not give freely. You must take what the mountain offers. Kill 5 owls and bring their carcasses to me.\n\nYes, we ask you to return the whole body to us, as we waste nothing provided by such graceful creatures.",done=0,ends={npc={256650}},factions={"Alliance"},frequency=0,group=0,level=57,objectives={{need=5,text="0/5 Intact Owl Body",type="item"}},races={"Human"},rewardMoney=11813,rewardXP=4500,seenBy=1,starts={npc={256650}},text="Bring 5 owl bodies to Elder Pinespeaker in Barkskin Burrow in Hyjal.",title="Wicked Wisdom",zone="Mount Hyjal"},
  [93834]={accepted={[2482]={21,78.7,1}},after={[94504]=1},classes={"PALADIN"},completionText="Gross. Yum!",description="Burrow beetles! They're a bane... and now they dig in our den more than their own. We beat them back and swing clubs when we see them skulk by, but they are quick, and to hide in the dark is their shield.\n\nIf you spot them as you climb our den, squash them! We will take their crushed shells and make a meal, so it is not all bad.",done=1,ends={npc={256629}},factions={"Alliance"},frequency=0,group=0,level=57,money=0,objectiveSpots={[1]={[2482]={21.2,78.8,7,22.5,78.3,3}}},objectives={{need=10,text="0/10 Burrow Beetle Bits",type="item"}},progressText="Hard to see till you stand on them--and then they dart away!",races={"Human"},required={{count=10,item=262803}},rewardXP=3000,rewards={{count=2,item=18253}},seenBy=1,starts={npc={256629}},text="Gather 10 Burrow Beetle Bits for Dala Fairmaw.",title="Burrow Beetles",xp=3000},
  [93925]={done=0,ends={npc={256978}},level=0,progressText="You show strength, but trust comes slow. Some still watch with hard eyes. I can help you earn their nod.\n\nDeadwood wear cords strung with fine beads of rare earth, smooth stones, and hard gifts of the mountain. These beads mark rank in their tribe. Bring me these signs to prove your deeds.\n\nFor every eight beads you bring, your name will weigh more with us.\nGo now, and let the wood see your will.",required={{count=8,item=263439}},seenBy=1,starts={npc={256978}},title="Beads for Brerufa"},
  [94504]={completionText="Our burrow grows more at ease with your presence now--you have shown you are on our path, our side, and bring good things. This is the way to keep, the way we live.",done=1,ends={npc={256627}},money=0,objectiveSpots={[1]={[2482]={29.3,61.3,1}}},rep={["Barkskin Burrow"]=200},rewardXP=3000,seenBy=1,title="Barkskin Beginnings",xp=3000},
  [95793]={accepted={[2482]={43.7,32.1,1}},after={[92015]=1},classes={"PALADIN"},description="Ah, a paladin. I see great strength and determination in you--qualities necessary to rid these lands of evil.\n\nThe demons that walked these lands during the great battle were defeated, yet some still remain. It is important to prevent them from escaping.\n\nThe ruins to the east are dangerous. Carry your strength into their den. Destroy the unwelcome before our lands perish.",done=0,factions={"Alliance"},frequency=0,group=0,level=59,objectiveNpcs={[1]={[249229]=4}},objectiveSpots={[1]={[2482]={47.4,32,1,47.9,33,2,49.9,33.4,1,54.3,35.1,1}}},objectives={{need=12,text="0/12 Felguard Sentinel slain",type="monster"}},offeredAt=59,races={"Human"},rewardMoney=20556,rewardXP=6400,seenBy=1,starts={npc={249052}},text="Slay 12 Felguard Sentinels in Dae'gun.",title="Stemming the Demon Tide",zone="Mount Hyjal"},
  [96077]={done=1,ends={npc={2329}},money=0,seenBy=1,title="Belle's Ring",xp=6200},
  [96252]={done=1,ends={npc={260825}},money=0,seenBy=1,title="Tarnished Treasures",xp=3100},
  [96296]={done=1,ends={npc={260825}},money=12788,seenBy=1,title="Fetid Corruption",xp=4650},
  [96558]={accepted={[2482]={27.5,51,1}},after={[93567]=1},choices={{count=1,item=274383},{count=1,item=274386},{count=1,item=274384}},classes={"PALADIN"},completionText="<Dark spirits lingered here, feeding on doubt. The magic animating frost wyrms twists their will, leaving unnatural spirits behind. \n\nWith the haunting presence fading, the contents of the battle cache reflect the light more brightly.>",description="Beneath the shattered stones of that watchtower lies a cache we buried in haste, when the world was starting to burn. What little we carried from Hyjal rests there still. Take it--you have earned that much.\n\nThe pull is increasing... the mountain no longer holds me as it once did. I am unsure if we will ever speak again.\n\nBecause of you, I remember who I was, and who we were. Go with my thanks, and let this spirit finally be at peace.",done=1,ends={object={613848}},factions={"Alliance"},frequency=0,group=0,level=60,money=0,objectiveSpots={[1]={[2482]={29,52.4,1}}},objectives={{need=1,text="0/1 Spirits put to rest",type="monster"}},races={"Human"},rewardXP=8300,rewards={{count=1,item=274800}},seenBy=1,starts={npc={265375}},text="Recover the Battle Cache buried on Mount Hyjal.",title="Soldier's Solace",xp=8300},
  [96561]={accepted={[2482]={29,52.5,1}},after={[96558]=1},classes={"PALADIN"},completionText="<Being the only possession you know for sure belonged to the war veteran, you take the Embroidered Scabbard from your bags. You place it--with Tobin's note--inside the broken fishing basket.\n\nStanding, you listen to the waterfall feeding the pond nearby.\n\nSeveral fish suddenly jump and make multiple splashes as you survey the water.>",description="<You unfold the simple parchment.>\n\nTo my Rowdy Redridge Rebels,\n\nThe lumberjacks here say the gulpers in that pond are biting like they're racing each other to the bait. Good fish, better eating. After this war is over, we're due an angling competition between friends.\n\nThe setting is simple: we stand on the center island and fish till the sun slips behind Hyjal's highest peak.\n\nWhoever catches the most, doesn't have to gut 'em for our dinner!\n\n-- Tobin --",done=1,ends={object={654150}},factions={"Alliance"},frequency=0,group=0,level=60,money=0,objectives={{need=1,text="1/1 Fishing Trip",type="item"}},progressText="<The old fishmonger's basket is shattered beyond repair.>",races={"Human"},required={{count=1,item=274795},{count=1,item=274800}},rewardXP=3300,seenBy=1,text="Find the fishing pond near the destroyed Alliance lumbermill in the Cradle of Tranquility.",title="Last Wishes",xp=3300},
  [96603]={description="Archmage Rhonin is presently abroad investigating a disturbance in the flow of magic across Azeroth. The Archmage has charged me with soliciting the aid of strong adventurers like yourself in gathering important field data to aid him.\n\nTake this Arcane Censer. While afflicted by its magic, you will be able to extract motes of unstable magic from the most skilled spell casters and other singularly powerful entities you may encounter. Bring me said motes and the Kirin Tor will be in your debt.",done=0,level=60,objectives={{need=10,text="0/10 Mote of Unstable Magic",type="item"}},seenBy=1,text="Bring 10 Motes of Unstable Magic to Archmage Celindra in Dalaran.",title="Unstable Magic",zone="City of Dalaran"},
  [96606]={accepted={[1438]={57.7,56.7,1}},classes={"ROGUE"},completionText="So now that we've learned the basics, why don't you go and learn a tradeskill from the trainers in the village nearby. They will also teach you how to create a camp fixture suitable to your new profession.",description="Greetings, rogue. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it.",done=1,ends={npc={265811}},factions={"Alliance"},frequency=0,group=0,level=6,money=0,objectiveSpots={[1]={[1438]={57.7,56.7,1}},[2]={[1438]={57.7,56.7,1}}},objectives={{need=1,text="0/1 Sit near the campfire (Optional)",type="object"},{need=1,text="0/1 Gain the Boosted Rest buff",type="object"}},races={"NightElf"},rewardXP=410,seenBy=1,starts={npc={265811}},text="Sit near Lyreena's Basic Campfire and wait until you receive the Boosted Rest buff.",title="The Great Outdoors",xp=410,xpByLevel={[5]=410},zone="Camping"},
  [96630]={completionText="Is that my journal? I've been missing this for a while. Thank you, rogue.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?",description="<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\n\nThere are multiple entries mentioning camping. It seems to be quite... fun.>",done=1,ends={npc={265811}},level=6,money=0,objectives={{need=1,text="Bring the journal to Lyreena Duskblade near Dolanaar.",type="log"}},progressText="Are you here to learn about camping in the wilderness?",required={{count=1,item=275022}},rewardXP=410,seenBy=1,text="Bring the journal to Lyreena Duskblade near Dolanaar.",title="The Adventurer",xp=410,xpByLevel={[5]=410},zone="Camping"},
  [96634]={accepted={[1438]={57.7,56.7,1}},after={[96606]=1},classes={"ROGUE"},description="So you want to learn more about camping, huh? Good for you, rogue. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.",done=0,factions={"Alliance"},frequency=0,group=0,level=6,objectives={{need=1,text="Learn cooking from Zarrin in Dolanaar",type="object"}},offeredAt=6,races={"NightElf"},rewardXP=270,seenBy=1,starts={npc={265811}},text="Speak with Zarrin in Dolanaar to learn to become a cook.",title="Camping 101: Cooking",zone="Camping"},
  [96666]={accepted={[2482]={21.7,79.4,1}},after={[94504]=1},classes={"PALADIN"},description="Barkskin speak more good on you, friend, but there is yet more for you to do.\n\nRaise your hand to our foes. Honor our ways.\n\nWe watch close, and then we will have more to say to you.",done=0,ends={npc={256650}},factions={"Alliance"},frequency=0,group=0,level=57,objectives={{need=1,text="Neutral / Friendly Barkskin Burrow",type="reputation"}},races={"Human"},rewardXP=3000,seenBy=1,starts={npc={256650}},text="Raise your reputation with the Barkskin Burrow to Friendly.",title="Burrow Bonding",zone="Mount Hyjal"},
  [96800]={description="You there, paladin. I have a matter I could use assistance with.\n\nI just so happen to be writing a thesis on the ancient Wildhammer runemasters of Grim Batol, and there's a particular tome I need to complete my research. According to our ledgers, a mage by the name of Doan checked the book out of the old Dalaran library before the Third War and never returned it!\n\nArcanist Doan is now holed up in the Scarlet Monastery in Tirisfal Glades. Retrieve this book for me and you'll be well rewarded.",done=0,level=38,objectives={{need=1,text="0/1 The Lost Magic of the Runemasters",type="item"}},seenBy=1,text="Retrieve the book The Lost Magic of the Runemasters from the Scarlet Monastery.",title="Past Due",zone="Scarlet Monastery"},
  [96959]={accepted={[2482]={49.4,32.6,1}},classes={"PALADIN"},description="War.\n\nBy the time I heeded the call of our clans, the battle had passed, and only ashes answered my blade.\n\nMy purpose is forged anew.\n\nThis mountain remembers strength--ancient power riding its winds and holding its water. I would earn the right to walk its spine, to reach the fallen stronghold that lies upon the road to the summit.\n\nDemons profane these graves. Before I fight at your side, I must know you stand capable. Light the two bonfires and return to me. Their flames draw our enemy out.",done=0,factions={"Alliance"},frequency=0,group=0,level=59,objectives={{need=1,text="0/1 South Bonfire lit",type="object"},{need=1,text="0/1 Southeast Bonfire lit",type="object"}},offeredAt=59,races={"Human"},rewardXP=3200,seenBy=1,starts={npc={267121}},text="Light the two bonfires in Dae'gun and return to Yashiro.",title="Blademaster's Bonfires",zone="Mount Hyjal"},
  [96964]={description="If the hermit truly wants his little gambit to leave the nest and fly, it will likely need a potent energy source. One that can sustain itself without collapse.\n\n<Jereman looks to the sky and clacks her beak together as she considers.>\n\nAh, yes. I know just the clever creature we can consult. Go north into the area you mortals refer to as Dae'gun, the one with the demons, and seek out the fox Wild God Renalard. I believe he will have a solution to our little puzzle.",done=0,level=59,seenBy=1,text="Speak to the Wild God Renalard.",title="A Clever Creature",zone="Mount Hyjal"},
  [96991]={description="The climb grows steeper from here, as you say. Even an empty pack weighs on tired legs. I would ask another kindness of you, traveler. Take my excess gear and carry it ahead to the Summit, where Marn Euhron aids in restoring a foothold near Nordrassil.\n\nI will follow at my own pace when my ceremonies here are complete. When I arrive, I will reclaim them from him and assist him in their work. This way, we both honor the journey and gifts of the mountain.",done=0,level=59,objectives={{need=1,text="Deliver Galvinquam's Belongings to Marn Euhron in the Summit.",type="log"}},seenBy=1,text="Deliver Galvinquam's Belongings to Marn Euhron in the Summit.",title="Trail Assist",zone="Mount Hyjal"},
  [97173]={description="The Blackmaw furbolgs in the mountains overlooking Azshara have been dabbling in dark magic. While a primitive people being corrupted by demonic magic is nothing new for Azeroth, Lan'dalock and I would like to study their spell foci.\n\nTravel to the stronghold known as Blackmaw Hold and recover one of the Blackmaw Ritual Totems for us. Only the most powerful of the Blackmaw's shamans will be carrying one of these, so bring allies and take care.",done=0,level=59,objectives={{need=1,text="0/1 Blackmaw Ritual Totem",type="item"}},seenBy=1,text="Recover a Blackmaw Ritual Totem from Blackmaw Hold.",title="Blackmaw Magic",zone="Blackmaw Hold"},
  [97327]={description="It breaks my heart to admit, but my brothers and sisters inside Blackmaw Hold are irreparably corrupted.\n\nIf you bring me some of their personal belongings, I can at least give their families something to remember them by. Every bundle you recover will serve as a symbol of your service to my people.",done=0,level=60,objectives={{need=5,text="0/5 Blackmaw Pouch",type="item"}},seenBy=1,text="Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara.",title="Blackmaw Pouches",zone="Blackmaw Hold"},
  [97949]={accepted={[1438]={57.6,56.7,1}},after={[96606]=1},classes={"ROGUE"},description="Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\n\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up.",done=0,factions={"Alliance"},frequency=0,group=0,level=6,objectives={{need=1,text="Raise your skinning skill to 20",type="object"}},offeredAt=6,races={"NightElf"},rewardXP=270,seenBy=1,starts={npc={265811}},text="Speak with Radnaal Maneweaver on the road to Darnassus from Dolanaar to learn to craft a camping item for your profession once you have shown proficiency in your skill.",title="Camping 101: Skinning",zone="Camping"},
  [99046]={accepted={[1438]={56,59.5,1}},classes={"ROGUE"},description="The Council of the Forest sent a small group of sentinels to the Oracle Tree some time ago. The tree sends messages to our elders, and it falls to us to deliver them to Darnassus safely.\n\nI received word that our most recent runner has not yet arrived. The Oracle's messages vary in frequency, but it has been abnormally long.\n\nPlease head towards the Oracle Glade along the road to the west and check on her. It would have been Eralya Leafshadow's turn, and she is still in training. Elune guide you.",done=0,factions={"Alliance"},frequency=0,group=0,level=9,offeredAt=6,races={"NightElf"},rewardXP=80,seenBy=1,starts={npc={2081}},text="Search for Sentinel Eralya Leafshadow on the road leading to the Oracle Glade.",title="The Lost Runner",zone="Teldrassil"},
}
